head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

scwin.vScrenID = "ULDFIS00400_04.xml";
// 전역 변수 선언
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = ""; // 조회조건 결산일자
scwin.vArray = "";

/**
 *  화면이 최초 로드될때 실행되는 초기화 이벤트
 *  (초기 데이터 조회나 컴포넌트 설정)
 */

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
    scwin.init();
};

/**
 *  현재 로딩된 페이지가 초기화되거나 종료될때(다른 화면으로 이동하거나 페이지를 닫기전) 발생하는 이벤트
 *  (주로 SPA(Single Page Application) 환경에서 전역 자원을 해제하거나 메모리 누수 방지)
 */
scwin.onpageunload = function() {

};

// 일반 함수
/**
 *  화면 초기화
 */
scwin.init = function() {

    // 결산일자 조회
    $p.parent().frame_head.getWindow().scwin.fn_SrchAcntclsDt();
    scwin.search();

};

/**
 *  데이터셋 초기화.
 */
scwin.initDs = function() {

    dlt_consNotesInterCoTxnListRes.setData([]);

};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {

    //필수항목 체크
    vKisCd = $p.parent().frame_head.getWindow().scwin.fn_GetKisCd();
    vAcntclsDt = $p.parent().frame_head.getWindow().scwin.fn_GetAcntclsDt();

    if (vKisCd === "" || vAcntclsDt === "") {
        return false;
    }

    return true;

};

/**
 * 연결대상간주요거래  조회
 */
scwin.search = async function() {

    //데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크
    if (!scwin.chkValid()) {
        return;
    }

    dma_consNotesInterCoTxnInfoReq.set("kisCd", vKisCd);
    dma_consNotesInterCoTxnInfoReq.set("acntclsDt", vAcntclsDt);

    const sbmOptions = {
        id : "sbm_consNotesInterCoTxn",
        action : "/api/listing/nice/financial/cons-notes/inter-cotxn",
        method : "get",
        ref : "dma_consNotesInterCoTxnInfoReq",
        target : "dlt_consNotesInterCoTxnListRes|append",
        isProcessMsg : false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    dlt_consNotesInterCoTxnListRes.setJSON(res.responseJSON.body);

    scwin.appendContents();

};

/**
 * 연결대상간주요거래 정보 생성
 */
scwin.appendContents = function() {

    let strContent = "<div style='overflow-x:hidden;overflow-y:scroll;width:100%;height:575px;font-family:돋움체;'>";

    for (let nRow = 0; nRow < dlt_consNotesInterCoTxnListRes.getRowCount(); nRow++) {
        strContent = strContent + dlt_consNotesInterCoTxnListRes.getCellData(nRow, "ctnt") + "";
    }

    strContent = strContent + "</div>";
    const tbxInterCotxnObj = $p.getComponentById("tbx_interCotxn").render;
    tbxInterCotxnObj.innerHTML = strContent;
    tbx_interCotxn.setStyle("border", "1px solid blue");
    // 태그 제거후 &nbsp; 만 남는경우 조회된 데이터가 없습니다를 뿌려준다
    // 임시방편으로 만든것 NICE 신용평가에 요청해야 함

    const pattern = /<[^>]+>/g;
    const pan_Ctnt_text = strContent.replace(pattern, '');

};
